"""The unit table."""
from fractions import Fraction as F


class UnknownUnit(ValueError):
    pass


BASE = {
    "m": (F(1), (1, 0, 0)),
    "g": (F(1, 1000), (0, 1, 0)),
    "s": (F(1), (0, 0, 1)),
}
PREFIXES = {"k": F(1000), "c": F(1, 100), "m": F(1, 1000)}
GUILD = {
    "span": (F(9, 50), (1, 0, 0)),
    "pace": (F(3, 4), (1, 0, 0)),
    "league": (F(3600), (1, 0, 0)),
    "stone": (F(6), (0, 1, 0)),
    "quintal": (F(100), (0, 1, 0)),
    "tick": (F(3), (0, 0, 1)),
    "watch": (F(14400), (0, 0, 1)),
    "plot": (F(400), (2, 0, 0)),
    "push": (F(1), (1, 1, -2)),
}


def lookup(name):
    if name in GUILD:
        return GUILD[name]
    if name in BASE:
        return BASE[name]
    if len(name) > 1 and name[0] in PREFIXES and name[1:] in BASE:
        factor, dim = BASE[name[1:]]
        return PREFIXES[name[0]] * factor, dim
    raise UnknownUnit(name)

